layer.css:
@import url("https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,100..900;1,100..900&family=Rubik:ital,wght@0,300..900;1,300..900&display=swap");
[data-ryt="footer"] { color: rgb(255, 255, 255); background-color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: prompt, -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: prompt, -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.35s ease-in-out }
[data-ryt="header"] { border-bottom: 1px solid rgb(35, 66, 222); border-top: none }
[data-ryt="button"] { color: rgb(255, 255, 255); background-color: rgb(35, 66, 222); border-radius: 50%; font-family: prompt, -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 255, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1px; padding-right: 6px; padding-bottom: 1px; padding-left: 6px; transition: 0.35s ease-in-out }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: prompt, -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 56px; font-weight: 800; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"]:hover { outline-color: initial; box-shadow: none; background-color: rgb(27, 52, 179) }
[data-ryt="nav"] a::after { content: ""; display: block; height: 2px; margin-top: 2px; color: var(--ryt-text); background-color: rgb(35, 66, 222); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: prompt, -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: width 0.3s; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="nav"] a:hover { color: rgb(10, 88, 202); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: inherit; outline-color: initial; box-shadow: none; color: rgb(35, 66, 222); outline-color: initial; box-shadow: none }
[data-ryt="brand"]:hover { color: rgb(10, 88, 202); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: inherit; outline-color: initial; box-shadow: none; outline-color: initial; box-shadow: none }
